INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e46f5567-6432-575e-8477-a98190c58e91', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 1, 1, 'A mass on a string is whirled round a horizontal circle at a constant speed. In which direction is the mass moving at any instant?', 'diagram:circ-mass-on-string', 1, 'multiple_choice'::answer_type, 'Along the tangent to the circle', NULL, NULL, false, 'At every instant the velocity is along the tangent — at right angles to the radius (the string). That is why the mass flies off along a tangent if the string breaks. It is the ACCELERATION, not the velocity, that points towards the centre.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ce9c203d-f107-5f75-9ac4-57b9d68beaf1', 'e46f5567-6432-575e-8477-a98190c58e91', 'Towards the centre of the circle', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a1329dcb-9f1d-5808-8290-12135ae74798', 'e46f5567-6432-575e-8477-a98190c58e91', 'Directly away from the centre of the circle', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a017444a-8b4b-5f64-8623-11d107da960e', 'e46f5567-6432-575e-8477-a98190c58e91', 'Along the tangent to the circle', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9dce365d-c2ff-5376-bdfe-94afafd0ebf0', 'e46f5567-6432-575e-8477-a98190c58e91', 'Along the string', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e5934f3a-a98e-5c26-9f6a-e17688e60b27', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 2, 2, 'An object moves round a circle of radius r at a constant speed, taking a time T (the period) for each revolution. Which expression gives its speed?', NULL, 1, 'multiple_choice'::answer_type, '2πr/T', NULL, NULL, false, 'In one period the object travels once round the circumference, 2πr. Speed = distance ÷ time = 2πr/T. In A Level terms this is v = rω, where the angular speed is ω = 2π/T.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5ea27c6c-eece-50bf-ac81-a8e682064b5b', 'e5934f3a-a98e-5c26-9f6a-e17688e60b27', '2πr/T', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f30e1ab0-fc01-53c9-9f36-b75c8ba377b0', 'e5934f3a-a98e-5c26-9f6a-e17688e60b27', 'πr²/T', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('91823e92-bc04-5337-850e-b9e317618f66', 'e5934f3a-a98e-5c26-9f6a-e17688e60b27', '2πT/r', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('44289d0b-c991-55d9-9ea4-dafcdff03787', 'e5934f3a-a98e-5c26-9f6a-e17688e60b27', 'rT/2π', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d97aca72-ddc6-50fd-8a74-0179c66aa7fa', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 3, 3, 'An aircraft flies round a complete horizontal circle of radius 3622 m in 2.10 minutes, at a constant speed. Calculate its speed.', 'diagram:circ-aircraft-loop', 2, 'numeric'::answer_type, '180.6', 'm/s', NULL, false, 'Convert the time first: 2.10 min × 60 = 126 s. The angular speed is ω = 2π/T = 2π ÷ 126 = 0.0499 rad/s, so v = rω = 3622 × 0.0499 = 181 m/s. (Or directly: v = 2πr/T = 2π × 3622 ÷ 126.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c27da911-a41c-5fcb-b365-f7dd55350afa', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 4, 4, 'A referee swings her 40.0 g whistle round a horizontal circle of radius 0.500 m above her head at a constant speed, taking 1.40 s for each rotation. Calculate the speed of the whistle.', 'diagram:circ-whistle-plan', 1, 'numeric'::answer_type, '2.244', 'm/s', 0.05, false, 'ω = 2π/T = 2π ÷ 1.40 = 4.49 rad/s, and v = rω = 0.500 × 4.49 = 2.24 m/s. (Equivalently v = 2πr/T.) The whistle’s mass does not affect its speed.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('91afd2d7-8017-5bcd-a7e0-574f4f9bf3b4', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 5, 5, 'Jason stands near the edge of a merry-go-round that turns clockwise at a constant speed, as shown. What is the direction of his velocity at the instant shown?', 'diagram:circ-merry-go-round', 1, 'multiple_choice'::answer_type, 'Along the tangent to his circular path, in the direction the merry-go-round is turning', NULL, NULL, false, 'Velocity is always along the tangent to the path, pointing the way the object is going. The merry-go-round turns clockwise, so Jason’s velocity is along the tangent in the clockwise sense — at right angles to the radius from the centre to him.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1e220a49-c806-5578-9a38-68592b4deeec', '91afd2d7-8017-5bcd-a7e0-574f4f9bf3b4', 'Towards the centre of the merry-go-round', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e5ec45ea-5dde-5aa0-bba2-396ef4e04a89', '91afd2d7-8017-5bcd-a7e0-574f4f9bf3b4', 'Directly away from the centre of the merry-go-round', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ab24a4b4-65a4-59f6-91d0-3f86f626e811', '91afd2d7-8017-5bcd-a7e0-574f4f9bf3b4', 'Along the tangent to his path, against the direction the merry-go-round is turning', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7df64e9c-6e67-5e1d-bfa1-fdde29f2053c', '91afd2d7-8017-5bcd-a7e0-574f4f9bf3b4', 'Along the tangent to his circular path, in the direction the merry-go-round is turning', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a038589a-bb16-5b41-bd46-599d79c1801a', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 6, 6, 'A suitcase rides on a horizontal circular conveyor belt of radius 7.0 m that turns clockwise at a constant speed. At the instant shown the suitcase is at the right-hand side of the circle. In which direction is it moving?', 'diagram:circ-baggage-belt', 1, 'multiple_choice'::answer_type, 'Along the tangent, towards the bottom of the diagram', NULL, NULL, false, 'The velocity is along the tangent, at right angles to the radius. At the right-hand side of the circle, a clockwise belt is carrying the suitcase straight down the page at that instant.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fe5a396b-959c-59e9-b06f-7e6d37f25b08', 'a038589a-bb16-5b41-bd46-599d79c1801a', 'Along the tangent, towards the top of the diagram', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7c79fe04-44e9-556f-9622-916060e4b1cb', 'a038589a-bb16-5b41-bd46-599d79c1801a', 'Towards the centre of the belt', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('015b235d-be05-5bc9-9fdf-5f29abd88fda', 'a038589a-bb16-5b41-bd46-599d79c1801a', 'Away from the centre of the belt', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('717d90bc-71a3-5e7a-9b09-8a3df94408d3', 'a038589a-bb16-5b41-bd46-599d79c1801a', 'Along the tangent, towards the bottom of the diagram', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f0f22088-29b1-551c-abab-9a4311062631', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 7, 7, 'The suitcase on the circular belt moves at a constant speed. Why is its motion described as accelerated?', 'diagram:circ-baggage-belt', 1, 'multiple_choice'::answer_type, 'Its velocity keeps changing direction, and a change in velocity is an acceleration', NULL, NULL, false, 'Acceleration is the rate of change of VELOCITY, and velocity is a vector. The speed stays the same but the direction changes continuously, so the velocity changes and the suitcase accelerates — towards the centre of the circle.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2686c83a-f59e-5473-bb49-b075c6bc1d00', 'f0f22088-29b1-551c-abab-9a4311062631', 'Its velocity keeps changing direction, and a change in velocity is an acceleration', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bc8f39d3-f272-538e-932c-c3eb5dcdb307', 'f0f22088-29b1-551c-abab-9a4311062631', 'It is not accelerated — its speed does not change', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f7068339-a4bc-58c3-8c89-81a0ec6c99ac', 'f0f22088-29b1-551c-abab-9a4311062631', 'The belt keeps speeding up and slowing down', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3bfe4e04-01d8-5acd-a961-f64cc8fa18ec', 'f0f22088-29b1-551c-abab-9a4311062631', 'Its acceleration points along its direction of motion', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('59a3817a-41f1-55e7-8063-67b0f7e37944', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 8, 8, 'Janet swings a ball on a string round a horizontal circle above her head at a constant speed. Which statement explains why the ball is accelerating?', 'diagram:circ-ball-overhead', 2, 'multiple_choice'::answer_type, 'The direction of its velocity changes all the time, so its velocity changes', NULL, NULL, false, 'Velocity is speed in a particular direction. Going round the circle the ball’s direction changes continuously, so its velocity changes even though its speed doesn’t — and a changing velocity is an acceleration (towards the centre, a = v²/r).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('42fb43ae-69b0-59f4-a6aa-e3dc0f24a1c3', '59a3817a-41f1-55e7-8063-67b0f7e37944', 'Its speed increases every time it goes round', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('35c0e9db-54b8-5d31-bd28-3edb1e259493', '59a3817a-41f1-55e7-8063-67b0f7e37944', 'The direction of its velocity changes all the time, so its velocity changes', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b0e95349-47f3-5201-9d95-14a7bf8cf85e', '59a3817a-41f1-55e7-8063-67b0f7e37944', 'The string pulls it outwards, away from Janet’s hand', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7c1591fb-aec0-5361-9460-6af9fb1e1b87', '59a3817a-41f1-55e7-8063-67b0f7e37944', 'It is not accelerating, because its speed is constant', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b95fc056-5ed2-576a-b07d-870e82da4072', '68a0e773-5e33-5982-9251-befc479a5b0e', '0245e29c-acd6-5c5f-b1b3-bf9431a0fa6b', 'a-level', '12.1', '9702 12.1 Kinematics of uniform circular motion', 9, 9, 'Jon spins Ana round a horizontal circle on the ice, holding her by the arm. While she is still moving in the circle he lets go. Ignoring friction from the ice, how does Ana move immediately afterwards?', 'diagram:circ-skaters', 2, 'multiple_choice'::answer_type, 'In a straight line along the tangent to the circle, at the speed she had when he let go', NULL, NULL, false, 'Once Jon lets go there is no horizontal force on Ana (the ice is frictionless), so by Newton’s first law her velocity stays constant: same speed, same direction. At the moment of release that direction was along the tangent, so she glides off in a straight line along the tangent at her circling speed.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('075b4a11-e892-5394-bf7e-1bbdf819c480', 'b95fc056-5ed2-576a-b07d-870e82da4072', 'Straight outwards, directly away from Jon', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ad76731a-7ffd-5ccb-a818-897be22f8ea9', 'b95fc056-5ed2-576a-b07d-870e82da4072', 'In a straight line along the tangent to the circle, at the speed she had when he let go', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4fa23abf-31b1-5f86-bbfd-f0581ce78f2d', 'b95fc056-5ed2-576a-b07d-870e82da4072', 'She keeps going round the same circle, gradually slowing down', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('625d0ad5-3555-5898-9190-69787f4bde63', 'b95fc056-5ed2-576a-b07d-870e82da4072', 'Along a curved path that spirals outwards', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ba31c93e-a920-5f77-870d-fc1aaf1d415f', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 1, 1, 'An object moves round a circle at a constant speed. In which direction does its acceleration point?', 'diagram:circ-mass-on-string', 1, 'multiple_choice'::answer_type, 'Towards the centre of the circle', NULL, NULL, false, 'The change in velocity, Δv, between two nearby points on the circle always points towards the centre, so the acceleration does too. That is why it is called centripetal (“centre-seeking”) acceleration, of size a = v²/r = rω².', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5d762b69-5f44-550d-aac2-3020cf4dc068', 'ba31c93e-a920-5f77-870d-fc1aaf1d415f', 'Along the tangent, in the direction of motion', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('be47f283-c2dc-5f6c-bf16-4d86a2268c5e', 'ba31c93e-a920-5f77-870d-fc1aaf1d415f', 'Directly away from the centre of the circle', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('87085290-bec6-5aeb-8058-57b4da10cdec', 'ba31c93e-a920-5f77-870d-fc1aaf1d415f', 'Nowhere — it has no acceleration, because its speed is constant', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b7e55cbd-f73b-5a8c-9cef-7e9345210e98', 'ba31c93e-a920-5f77-870d-fc1aaf1d415f', 'Towards the centre of the circle', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6a2dd50f-5ae3-5ebe-9b3a-9a79c7e17832', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 2, 2, 'Which force provides the centripetal force in each case? (1) A mass whirled round in a circle on the end of a string. (2) A car rounding a corner on a flat road. (3) The Moon orbiting the Earth.', NULL, 1, 'multiple_choice'::answer_type, '(1) tension, (2) friction, (3) gravity', NULL, NULL, false, 'Centripetal force is not a new kind of force: it is the resultant force towards the centre, and some real force has to supply it. On a string it is the tension; for a car on a flat road it is the sideways friction between the tyres and the road; for the Moon it is the Earth’s gravitational pull.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c04da58a-89cb-5d40-8f08-c25a6e4f6ea7', '6a2dd50f-5ae3-5ebe-9b3a-9a79c7e17832', '(1) tension, (2) the engine’s driving force, (3) gravity', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c0fc74cb-b74f-5189-b886-5ac19358e3a2', '6a2dd50f-5ae3-5ebe-9b3a-9a79c7e17832', '(1) weight, (2) friction, (3) centrifugal force', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d3e1c493-8201-505c-b56d-940a7200c34f', '6a2dd50f-5ae3-5ebe-9b3a-9a79c7e17832', '(1) tension, (2) friction, (3) gravity', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3582e0e5-e9ef-5331-a52f-ddb92c620cb3', '6a2dd50f-5ae3-5ebe-9b3a-9a79c7e17832', '(1) centrifugal force, (2) friction, (3) the Moon’s momentum', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('54b5e744-c837-5f51-988b-4558ec94e30e', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 3, 3, '“Centripetal” means centre-seeking and “centrifugal” means centre-fleeing. In an inertial frame of reference (one in which Newton’s laws hold), which statement about a “centrifugal force” on an object moving in a circle is correct?', NULL, 2, 'multiple_choice'::answer_type, 'It is not a real force: nothing pushes the object outwards — it only needs a force inwards to stop it moving in a straight line', NULL, NULL, false, 'In an inertial frame only real forces act. By Newton’s first law an object keeps moving in a straight line unless a force deflects it, so a circling object needs a resultant force INWARDS, not outwards. The “outward force” we seem to feel is our own inertia — an apparent force that only appears in a rotating frame of reference.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8dc46972-f620-52e1-9b60-8e3309219be1', '54b5e744-c837-5f51-988b-4558ec94e30e', 'It is a real outward force that balances the centripetal force', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e641cb39-4319-58f2-97fd-6545aea2625c', '54b5e744-c837-5f51-988b-4558ec94e30e', 'It is the reaction to the centripetal force, and it acts on the object itself', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('66d745d6-2b77-5fc9-8a9d-accd55f04a14', '54b5e744-c837-5f51-988b-4558ec94e30e', 'It only acts while the object’s speed is changing', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('62dc0c0f-7b18-50f7-b59f-ec2629cebd60', '54b5e744-c837-5f51-988b-4558ec94e30e', 'It is not a real force: nothing pushes the object outwards — it only needs a force inwards to stop it moving in a straight line', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d13ffebd-50d4-55aa-bacc-8d446d9be336', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 4, 4, 'Riding in the back seat of a car that turns a corner, you slide across the seat as if pushed outwards, away from the centre of the turn. Which is the correct explanation?', NULL, 2, 'multiple_choice'::answer_type, 'By Newton’s first law your body tends to keep moving in a straight line; the car turns beneath you until the seat, seatbelt or door pushes you towards the centre of the turn', NULL, NULL, false, 'Nothing pushes you outwards. You carry on in a straight line (inertia) while the car curves away beneath you, so relative to the car you seem to slide outwards. The real forces on you — friction from the seat, then the push of the seatbelt or door — act towards the centre of the turn and give you your centripetal acceleration.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f774b517-609c-5b32-b489-3a473927a140', 'd13ffebd-50d4-55aa-bacc-8d446d9be336', 'A centrifugal force pushes you outwards, away from the centre of the turn', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2e31547f-75c4-51f7-84f3-9fb08b7d052a', 'd13ffebd-50d4-55aa-bacc-8d446d9be336', 'The centripetal force on you acts outwards, away from the centre', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fe03849b-8ed4-5cb1-a028-9fb50a59ec1f', 'd13ffebd-50d4-55aa-bacc-8d446d9be336', 'Your weight gains a sideways component while the car turns', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ef8211f6-1fd3-5168-b872-ee9c4d442661', 'd13ffebd-50d4-55aa-bacc-8d446d9be336', 'By Newton’s first law your body tends to keep moving in a straight line; the car turns beneath you until the seat, seatbelt or door pushes you towards the centre of the turn', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6c3c7087-3e4c-5a8c-90a0-f45a154ac94a', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 5, 5, 'A 0.50 kg mass on a frictionless table is tied to a string that passes through a hole in the centre of the table to a hanging mass. The 0.50 kg mass moves round a circle of radius 0.20 m at 2.3 m/s. Calculate the centripetal force on it.', 'diagram:circ-table-hole', 2, 'numeric'::answer_type, '13.22', 'N', NULL, false, 'F = mv²/r = 0.50 × 2.3² ÷ 0.20 = 0.50 × 5.29 ÷ 0.20 = 13.2 N. The tension in the string supplies this force.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0669d584-a1aa-5a11-a64a-c87e1fcd818b', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 6, 6, 'The 0.50 kg mass circles at 2.3 m/s on a radius of 0.20 m, held in its circle by a string that runs through the hole in the frictionless table to a hanging mass M, which stays at rest. Calculate M. Take g = 9.81 m/s².', 'diagram:circ-table-hole', 3, 'numeric'::answer_type, '1.348', 'kg', 0.05, false, 'The hanging mass is in equilibrium, so the tension equals its weight, Mg. The same tension is the centripetal force on the circling mass, mv²/r = 0.50 × 2.3² ÷ 0.20 = 13.2 N. So Mg = 13.2 N and M = 13.2 ÷ 9.81 = 1.35 kg.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b3105f59-de48-5781-82c6-7dbf1816f282', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 7, 7, 'A car travelling at 14 m/s goes round an unbanked (flat) bend of radius 96 m. Calculate its centripetal acceleration.', 'diagram:circ-flat-bend', 1, 'numeric'::answer_type, '2.042', 'm/s²', 0.05, false, 'a = v²/r = 14² ÷ 96 = 196 ÷ 96 = 2.04 m/s², directed towards the centre of the bend.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4f17f8dd-6e91-5d9b-9af4-2f9e96a5c429', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 8, 8, 'The car goes round the flat bend of radius 96 m at 14 m/s, with sideways friction from the road providing all of the centripetal force. The friction force can be at most μ × (normal contact force), where μ is the coefficient of friction. Calculate the minimum value of μ that lets the car round the bend. Take g = 9.81 m/s².', 'diagram:circ-flat-bend', 3, 'numeric'::answer_type, '0.2081', NULL, NULL, false, 'On a flat road the normal contact force equals the weight, mg, so the largest possible friction force is μmg. It must be at least the centripetal force: μmg = mv²/r. The mass cancels, so μ = v²/(rg) = 14² ÷ (96 × 9.81) = 2.04 ÷ 9.81 = 0.21.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dcf5296b-eaf3-5b9b-bb7c-979ec5ff00c6', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 9, 9, 'A mass on a string moves in a vertical circle. T is the tension in the string and mg is the weight of the mass. Which expressions give the resultant (centripetal) force on the mass at the top and at the bottom of the circle?', 'diagram:circ-ball-cord-top-bottom', 2, 'multiple_choice'::answer_type, 'Top: T + mg.   Bottom: T − mg', NULL, NULL, false, 'The resultant force must point towards the centre. At the top the string pulls down (towards the centre) and so does the weight, so they add: F = T + mg. At the bottom the string pulls up (towards the centre) but the weight still pulls down, so F = T − mg. That is why the tension is greatest at the bottom.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('400d0ee5-4037-53f8-951f-a9443970f379', 'dcf5296b-eaf3-5b9b-bb7c-979ec5ff00c6', 'Top: T − mg.   Bottom: T + mg', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f904ca77-1f31-563c-abbb-4558412f5277', 'dcf5296b-eaf3-5b9b-bb7c-979ec5ff00c6', 'Top: T + mg.   Bottom: T − mg', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('547dc8eb-9911-5451-9eaf-f549ee8dd976', 'dcf5296b-eaf3-5b9b-bb7c-979ec5ff00c6', 'Top: T + mg.   Bottom: T + mg', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4ee08e1d-aa07-5047-a702-92a57ebd2d31', 'dcf5296b-eaf3-5b9b-bb7c-979ec5ff00c6', 'Top: T.   Bottom: T', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e282e8d9-7fa9-5e19-a9c3-76cae0f2d272', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 10, 10, 'A 1.7 kg object is swung on the end of a 0.60 m string in a vertical circle, taking 1.1 s for each revolution. Treating its speed as constant, calculate the tension in the string at the top of the circle. Take g = 9.81 m/s².', 'diagram:circ-vertical-string', 3, 'numeric'::answer_type, '16.6', 'N', 0.05, false, 'The centripetal force needed is F = mrω², with ω = 2π/T = 2π ÷ 1.1 = 5.71 rad/s: F = 1.7 × 0.60 × 5.71² = 33.3 N. At the top the tension and the weight both point towards the centre: T + mg = F. So T = 33.3 − (1.7 × 9.81) = 33.3 − 16.7 = 16.6 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b5202edf-0e27-59db-ab66-1f05015611ed', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 11, 11, 'The same 1.7 kg object on a 0.60 m string goes round its vertical circle once every 1.1 s. Treating its speed as constant, calculate the tension in the string at the bottom of the circle. Take g = 9.81 m/s².', 'diagram:circ-vertical-string', 3, 'numeric'::answer_type, '49.96', 'N', NULL, false, 'As before, F = m × 4π²r/T² = 1.7 × 4π² × 0.60 ÷ 1.1² = 33.3 N. At the bottom the tension pulls up, towards the centre, while the weight pulls down: T − mg = F. So T = 33.3 + 16.7 = 50.0 N — about three times the tension at the top.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('91226059-1d55-5ea5-8359-3fd72509d33f', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 12, 12, 'A mass on a string is swung in a vertical circle with only just enough speed to keep it moving in the circle. What is the tension in the string when the mass is at the top?', NULL, 2, 'multiple_choice'::answer_type, 'Zero — its weight alone provides the centripetal force', NULL, NULL, false, 'At the top, T + mg = mv²/r. The slowest the mass can go is when the string is only just taut, T = 0, so mg = mv²/r. The resultant force is then just the weight: for that instant the mass is “weightless”, in free fall, like an object in orbit.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a0649427-73a6-506b-b8eb-1ac89882dc8b', '91226059-1d55-5ea5-8359-3fd72509d33f', 'Equal to the weight of the mass', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('af092b3b-4d96-5faa-b280-f14bc54c566e', '91226059-1d55-5ea5-8359-3fd72509d33f', 'Zero — its weight alone provides the centripetal force', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('99a949f0-e40e-51cc-9bab-5604545fc3aa', '91226059-1d55-5ea5-8359-3fd72509d33f', 'Twice the weight of the mass', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dc265411-0c52-5f74-9d24-4184b554aad8', '91226059-1d55-5ea5-8359-3fd72509d33f', 'Equal to the centripetal force plus the weight', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('eb0132e9-c479-5630-b3f3-b7db57d0013d', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 13, 13, 'An object is swung in a vertical circle of radius 0.75 m. Calculate the minimum speed it must have at the top of the circle to stay in circular motion. Take g = 9.81 m/s².', 'diagram:circ-vertical-top', 2, 'numeric'::answer_type, '2.712', 'm/s', NULL, false, 'At the minimum speed the weight alone provides the centripetal force at the top: mg = mv²/r. The mass cancels, so v = √(gr) = √(9.81 × 0.75) = 2.71 m/s. Any slower and the weight would be more than the centripetal force needed, so the object would fall inside the circle.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('97b950f9-1426-5b42-85f7-ff2b7497c3ba', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 14, 14, 'A car travels at a constant speed round a frictionless banked bend, as shown. Which forces act on the car?', 'diagram:circ-banked-road', 2, 'multiple_choice'::answer_type, 'Only its weight and the normal contact force from the road', NULL, NULL, false, 'On a frictionless bend only two real forces act: the weight (vertically down) and the normal contact force (perpendicular to the road surface). The centripetal force is not an extra force — it is the resultant of these two.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2d340320-97f7-5b55-a5f0-4e1de5e5197b', '97b950f9-1426-5b42-85f7-ff2b7497c3ba', 'Its weight, the normal contact force and a centripetal force', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9c887759-3a9b-58b9-86ef-4dcc08a3f069', '97b950f9-1426-5b42-85f7-ff2b7497c3ba', 'Its weight, the normal contact force and friction up the slope', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b976c615-2b2b-5eaf-931e-aa8bb8b118fd', '97b950f9-1426-5b42-85f7-ff2b7497c3ba', 'Only its weight and the normal contact force from the road', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c664baad-a7bb-5574-8491-072a3240e037', '97b950f9-1426-5b42-85f7-ff2b7497c3ba', 'Its weight, the normal contact force and an outward centrifugal force', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('356e9aa4-87a4-5f7f-b201-0ea8caa734b3', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 15, 15, 'On a frictionless banked bend, what provides the centripetal force on the car?', 'diagram:circ-banked-road', 3, 'multiple_choice'::answer_type, 'The horizontal component of the normal contact force, towards the centre of the bend', NULL, NULL, false, 'The normal contact force is tilted towards the centre of the bend. Its vertical component balances the weight (N cosθ = mg) and its horizontal component is the centripetal force (N sinθ = mv²/r). So on a banked bend the normal force is larger than the weight: it both holds the car up and pushes it round.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('de1aec26-f46c-5db2-90b4-523a2521332d', '356e9aa4-87a4-5f7f-b201-0ea8caa734b3', 'The component of the car’s weight down the slope', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('646be0b9-b5e4-5c8a-b097-79a640ac97ee', '356e9aa4-87a4-5f7f-b201-0ea8caa734b3', 'The vertical component of the normal contact force', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ed897283-36ce-5529-b336-1bfce568aed1', '356e9aa4-87a4-5f7f-b201-0ea8caa734b3', 'Friction between the tyres and the road', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('72dc8763-94f5-52e4-8ff2-795110e818c7', '356e9aa4-87a4-5f7f-b201-0ea8caa734b3', 'The horizontal component of the normal contact force, towards the centre of the bend', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c1b8de0b-fcb4-5350-9a7b-2191ca22ab95', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 16, 16, 'A bend of radius 475 m is to be banked so that a car can go round it at 22 m/s without needing any friction. Calculate the angle θ at which the road must be banked. Take g = 9.81 m/s².', 'diagram:circ-banked-road-475', 3, 'numeric'::answer_type, '5.93', '°', NULL, false, 'Vertically N cosθ = mg; horizontally N sinθ = mv²/r. Dividing, tanθ = v²/(rg) = 22² ÷ (475 × 9.81) = 484 ÷ 4660 = 0.104, so θ = 5.93°, about 6°.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('351ac04b-4b63-5fc6-9832-ad3232049101', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 17, 17, 'A 0.25 kg toy plane on a string flies round a horizontal circle of radius 0.80 m. The string makes an angle of 28° with the vertical. Calculate the period of the plane’s motion. Take g = 9.81 m/s².', 'diagram:circ-toy-plane', 4, 'numeric'::answer_type, '2.461', 's', NULL, false, 'Weight: mg = 0.25 × 9.81 = 2.45 N. The tension’s vertical component balances the weight and its horizontal component is the centripetal force, so tan28° = F/mg and F = 2.45 × tan28° = 1.30 N. Then F = m × 4π²r/T² gives T = √(m × 4π²r ÷ F) = √(0.25 × 4π² × 0.80 ÷ 1.30) = 2.46 s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('65c3cdf1-ec0a-5bc1-8c36-b0cd02815ead', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 18, 18, 'Alice rides in a car on a theme-park ride. The car travels round a circular track that is banked, as shown, and friction is negligible. Which two forces act on the car?', 'diagram:circ-theme-park', 2, 'multiple_choice'::answer_type, 'Its weight, vertically downwards, and the normal reaction from the track, at right angles to the track surface', NULL, NULL, false, 'With no friction the track can only push at right angles to its surface — the normal reaction, tilted towards the centre of the circle. The other force is the weight, vertically down. Their resultant is horizontal and towards the centre: it IS the centripetal force, not a third force.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7b366657-4712-5bab-ae2d-280263212670', '65c3cdf1-ec0a-5bc1-8c36-b0cd02815ead', 'Its weight, vertically downwards, and the normal reaction from the track, at right angles to the track surface', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b2ab31bf-1c45-52a2-8864-49cfd84278c2', '65c3cdf1-ec0a-5bc1-8c36-b0cd02815ead', 'Its weight, vertically downwards, and the centripetal force, horizontally towards the centre', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('652369f0-4b76-5168-b844-790af35363a9', '65c3cdf1-ec0a-5bc1-8c36-b0cd02815ead', 'The normal reaction, vertically upwards, and friction, down the slope', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('90fd0261-56d7-5064-b729-b4f31bb9b01d', '65c3cdf1-ec0a-5bc1-8c36-b0cd02815ead', 'Its weight, at right angles to the track surface, and the normal reaction, vertically upwards', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1d0f1bc8-ffb1-536a-a2fa-e566c0ff90b7', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 19, 19, 'The mass of Alice’s car and its passengers is 9.60 × 10² kg, and the frictionless track is banked at 20° to the horizontal. Calculate the size of the centripetal force on the car. Take g = 9.81 m/s².', 'diagram:circ-theme-park', 3, 'numeric'::answer_type, '3428', 'N', NULL, false, 'In the vector diagram the normal reaction N is at 20° to the vertical, and its vertical component balances the weight: N cos20° = mg. The resultant of N and the weight is horizontal: F = mg tan20° = 960 × 9.81 × tan20° = 9418 × 0.364 = 3.43 × 10³ N, towards the centre of the circle.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('672cae21-00df-5c43-8479-537c842910b7', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 20, 20, 'A 0.250 kg ball on the end of a cord 1.20 m long is swung in a vertical circle. At the position shown its speed is 4.00 m/s. Calculate the centripetal force on the ball at this instant.', 'diagram:circ-ball-cord', 1, 'numeric'::answer_type, '3.333', 'N', NULL, false, 'F = mv²/r = 0.250 × 4.00² ÷ 1.20 = 4.00 ÷ 1.20 = 3.33 N, directed along the cord towards the centre of the circle.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7559d645-3a1b-59db-b2cc-d888da215e94', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 21, 21, 'Why does a ball swung on a cord in a vertical circle move fastest at the bottom of the circle?', 'diagram:circ-ball-cord-top-bottom', 2, 'multiple_choice'::answer_type, 'As it goes down from the top to the bottom, gravitational potential energy is converted to kinetic energy', NULL, NULL, false, 'The tension is always at right angles to the ball’s velocity, so it does no work. Only gravity changes the ball’s energy: going down it loses gravitational potential energy and gains the same amount of kinetic energy, so it is fastest at the lowest point and slowest at the top.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7fc46602-f277-5f95-a172-dcc3b27ef419', '7559d645-3a1b-59db-b2cc-d888da215e94', 'As it goes down from the top to the bottom, gravitational potential energy is converted to kinetic energy', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bce5d799-1417-5fd4-b2e5-83e595005fe3', '7559d645-3a1b-59db-b2cc-d888da215e94', 'The tension in the cord is greatest at the bottom, so it pulls the ball faster', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5a6ae8f9-7020-52b7-a571-eb792896c0c7', '7559d645-3a1b-59db-b2cc-d888da215e94', 'The centripetal force is smallest at the bottom', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fcf9825e-22c7-5e78-aaa7-e99b0b92fbe1', '7559d645-3a1b-59db-b2cc-d888da215e94', 'Its weight acts along its direction of motion at the bottom', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aa1e6d60-d93d-5b2a-b7a8-60ce96ef10c6', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 22, 22, 'The ball is swung in a vertical circle with the cord taut all the way round. How does the tension in the cord at the bottom of the circle compare with the tension at the top?', 'diagram:circ-ball-cord-top-bottom', 3, 'multiple_choice'::answer_type, 'It is larger at the bottom', NULL, NULL, false, 'At the top the weight helps to provide the centripetal force: T_top = mv_top²/r − mg. At the bottom the tension must supply the centripetal force AND hold up the weight: T_bottom = mv_bottom²/r + mg. The ball is also faster at the bottom, so the tension there is larger for both reasons.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('93206396-4e69-5712-8575-b2e78c9a69e8', 'aa1e6d60-d93d-5b2a-b7a8-60ce96ef10c6', 'It is larger at the top', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7f6e3ccc-4398-5d36-a259-edbd88cf939d', 'aa1e6d60-d93d-5b2a-b7a8-60ce96ef10c6', 'It is larger at the bottom', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7312f456-e2d9-53ac-bb23-da6667264e52', 'aa1e6d60-d93d-5b2a-b7a8-60ce96ef10c6', 'It is the same at the top and the bottom', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('168a5f65-3fe9-5628-a9ba-60c3a7d36c57', 'aa1e6d60-d93d-5b2a-b7a8-60ce96ef10c6', 'It is zero at the bottom', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6d20cd51-b8ec-5129-b970-cbd9de54a7f4', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 23, 23, 'Compare the centripetal (resultant) force on the ball at the top and at the bottom of its vertical circle.', 'diagram:circ-ball-cord-top-bottom', 3, 'multiple_choice'::answer_type, 'Both point towards the centre — down at the top and up at the bottom — and it is larger at the bottom', NULL, NULL, false, 'The centripetal force always points towards the centre, so it is downwards at the top and upwards at the bottom. Its size is mv²/r, and the ball is faster at the bottom, so the centripetal force is larger there.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7036c80f-d8a4-5d4f-9149-71395722ba58', '6d20cd51-b8ec-5129-b970-cbd9de54a7f4', 'Both point towards the centre — down at the top and up at the bottom — and it is larger at the bottom', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('95584c82-d1e1-509c-a6da-d510b2defe7c', '6d20cd51-b8ec-5129-b970-cbd9de54a7f4', 'Both point downwards, and they are equal in size', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('90824b6f-145f-5b6d-a2bc-5f77a56b8a60', '6d20cd51-b8ec-5129-b970-cbd9de54a7f4', 'Both point towards the centre, and they are equal in size', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7b0be178-5ef2-5f08-8db8-a63b9475e752', '6d20cd51-b8ec-5129-b970-cbd9de54a7f4', 'It points away from the centre at the bottom', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('39f9d811-b01a-55aa-b44d-f1d02efe03e0', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 24, 24, 'The 0.250 kg ball is swung in a vertical circle on a cord 1.20 m long. Calculate the minimum speed it must have at the top of the circle for the cord to stay taut. Take g = 9.81 m/s².', 'diagram:circ-ball-cord-top', 2, 'numeric'::answer_type, '3.431', 'm/s', NULL, false, 'At the minimum speed the tension at the top is zero, so the weight alone provides the centripetal force: mg = mv²/r, giving v = √(gr) = √(9.81 × 1.20) = 3.43 m/s. Any slower and the weight is more than is needed to pull the ball round, so the cord goes slack and the ball leaves the circle.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7f074496-bd71-5271-84be-e6f95f983a33', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 25, 25, 'The ball has its minimum speed of 3.43 m/s at the top of the circle (cord 1.20 m). Using conservation of energy, calculate the angle θ from the top of the circle — measured at the centre, from the upward vertical — at which the ball’s speed has risen to 4.00 m/s. Take g = 9.81 m/s².', 'diagram:circ-ball-cord-angle', 4, 'numeric'::answer_type, '34.9', '°', NULL, false, 'Kinetic energy gained = potential energy lost: ½m(v² − v_top²) = mgΔh, so Δh = (4.00² − 3.43²) ÷ (2 × 9.81) = 0.216 m. The ball has dropped Δh = r − r cosθ below the top, so cosθ = 1 − Δh/r = 1 − 0.216 ÷ 1.20 = 0.820, and θ = 34.9°.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ea116edc-f280-5ef4-baf1-37f74e7d9f0d', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 26, 26, 'A 1.80 kg bob on a cord 1.55 m long swings as a conical pendulum, moving round a horizontal circle of radius 0.290 m. Calculate the angle θ between the cord and the vertical.', 'diagram:circ-conical-bob', 3, 'numeric'::answer_type, '10.78', '°', 0.05, false, 'The cord is the hypotenuse of a right-angled triangle whose side opposite θ is the radius: sinθ = r/L = 0.290 ÷ 1.55 = 0.187, so θ = 10.8°.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('207ecbf4-3101-5a3f-8b3e-7184a3af136e', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 27, 27, 'The 1.80 kg bob of a conical pendulum moves round a horizontal circle of radius 0.290 m on a cord 1.55 m long. Calculate the tension in the cord. Take g = 9.81 m/s².', 'diagram:circ-conical-bob', 3, 'numeric'::answer_type, '17.98', 'N', NULL, false, 'First the angle: sinθ = 0.290 ÷ 1.55, so θ = 10.8°. The bob neither rises nor falls, so the vertical component of the tension balances its weight: T cosθ = mg. T = (1.80 × 9.81) ÷ cos10.8° = 17.66 ÷ 0.982 = 18.0 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('290b853f-58d5-50c0-9f36-a3422af6959f', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 28, 28, 'Calculate the speed the 1.80 kg bob must have to move round its horizontal circle of radius 0.290 m on the 1.55 m cord. Take g = 9.81 m/s².', 'diagram:circ-conical-bob', 4, 'numeric'::answer_type, '0.7361', 'm/s', NULL, false, 'The horizontal component of the tension is the centripetal force, T sinθ = mv²/r, while vertically T cosθ = mg. Dividing, tanθ = v²/(rg), so v = √(rg tanθ) = √(0.290 × 9.81 × tan10.8°) = √(0.290 × 9.81 × 0.190) = 0.736 m/s. (With T = 18.0 N, v = √(T sinθ × r ÷ m) gives the same.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f6455672-d153-5732-802e-857828e86223', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 29, 29, 'The London Eye is a giant wheel with 32 passenger capsules evenly spaced round its rim. Each capsule has a mass of 1.0 × 10⁴ kg, is 68 m from the centre of the wheel and moves at a constant 0.26 m/s. Calculate the centripetal force that keeps a capsule moving in its vertical circle.', 'diagram:circ-observation-wheel', 1, 'numeric'::answer_type, '9.941', 'N', NULL, false, 'F = mv²/r = 1.0 × 10⁴ × 0.26² ÷ 68 = 676 ÷ 68 = 9.94 N — tiny compared with the capsule’s weight of about 10⁵ N, because the wheel turns so slowly.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9231366b-5e12-51ed-8ddc-df636d1b7a74', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 30, 30, 'A passenger stands on the floor of a capsule at the position shown, on the side of the turning wheel. Which forces act on her, and how do they give her centripetal force?', 'diagram:circ-observation-wheel', 3, 'multiple_choice'::answer_type, 'Her weight downwards, the normal contact force from the floor upwards (very slightly less than her weight) and a small sideways friction force from the floor towards the wheel’s axis; their resultant points at the centre of the wheel', NULL, NULL, false, 'She moves in a circle, so the resultant force on her must point towards the centre of the wheel — at this position, down and towards the axis. Gravity pulls her down, the floor pushes up with a little less than her weight, and friction from the floor pushes her sideways towards the axis. Together they give a small resultant, mv²/r, towards the centre.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('20385db8-b050-5c61-ae9b-8c109c735dce', '9231366b-5e12-51ed-8ddc-df636d1b7a74', 'Her weight downwards, the normal contact force from the floor upwards (very slightly less than her weight) and a small sideways friction force from the floor towards the wheel’s axis; their resultant points at the centre of the wheel', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('48c32112-8b30-5e10-9ac3-1faa33b08fe3', '9231366b-5e12-51ed-8ddc-df636d1b7a74', 'Only her weight and the normal contact force, which are equal and opposite, so there is no resultant force', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('32682329-932f-512f-9c6a-8eda01e25e80', '9231366b-5e12-51ed-8ddc-df636d1b7a74', 'Her weight, the normal contact force and an outward centrifugal force, which together balance', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('460e9c92-10e9-548a-bae1-2a2d7a9ca73b', '9231366b-5e12-51ed-8ddc-df636d1b7a74', 'Only her weight, which points towards the centre of the wheel', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d829902e-757a-50f2-a298-b5a910476f07', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 31, 31, 'Jon spins Ana round a horizontal circle on the ice by holding her arm, as shown. In which direction does the tension force from Jon’s arm act on Ana at the instant shown?', 'diagram:circ-skaters', 1, 'multiple_choice'::answer_type, 'Along the arm, towards Jon at the centre of the circle', NULL, NULL, false, 'Jon’s arm pulls Ana towards him, along the arm. Because Jon is at the centre, this tension points towards the centre of the circle — it is the centripetal force that keeps Ana on her circular path.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4b523b55-d6b4-5dbc-b4b1-d4f943405e42', 'd829902e-757a-50f2-a298-b5a910476f07', 'Along the tangent, in her direction of motion', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('94aee677-f874-5440-85c0-00bef36cd12c', 'd829902e-757a-50f2-a298-b5a910476f07', 'Along the arm, away from Jon', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c7e4f9de-e9a8-52cd-845c-e4bc16f7e434', 'd829902e-757a-50f2-a298-b5a910476f07', 'Vertically upwards', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('97b19d78-477b-5532-8ba4-e1462201be62', 'd829902e-757a-50f2-a298-b5a910476f07', 'Along the arm, towards Jon at the centre of the circle', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4b9dfc64-c794-5b78-8ef2-c2d55736c325', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 32, 32, 'Ana (mass 55 kg) moves round a horizontal circle of radius 0.95 m, and the tension force in Jon’s arm is 5.00 × 10² N. Calculate Ana’s speed, giving your answer to an appropriate number of significant figures.', 'diagram:circ-skaters', 2, 'numeric'::answer_type, '2.939', 'm/s', NULL, false, 'The tension is the centripetal force: T = mv²/r, so v = √(Tr/m) = √(5.00 × 10² × 0.95 ÷ 55) = √8.64 = 2.9 m/s — to 2 significant figures, because the radius and Ana’s mass are only given to 2 s.f.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('06ad98e5-6912-54b5-860d-7d25ac5e5399', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 33, 33, 'Jan swings a 10 kg iron ball on a steel wire round a horizontal circle, shown from above. In which direction is the ball’s acceleration at the instant shown?', 'diagram:circ-hammer-throw', 1, 'multiple_choice'::answer_type, 'Along the wire, towards Jan at the centre', NULL, NULL, false, 'In uniform circular motion the acceleration is centripetal: it points towards the centre of the circle — here along the wire, towards Jan — at right angles to the velocity.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('234abb6d-832d-5693-adf1-0740e764a167', '06ad98e5-6912-54b5-860d-7d25ac5e5399', 'In the direction of its velocity', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('90af3f9d-d3b2-59bd-bb95-ba4921d3db08', '06ad98e5-6912-54b5-860d-7d25ac5e5399', 'Along the wire, away from Jan', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('465042c5-72ea-5e8e-a861-61cb821e1095', '06ad98e5-6912-54b5-860d-7d25ac5e5399', 'Along the wire, towards Jan at the centre', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('28d0c98a-a5e0-5536-943a-9df3bac12f05', '06ad98e5-6912-54b5-860d-7d25ac5e5399', 'Nowhere — it has no acceleration, because it moves at a constant speed', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0fa5f4e5-11dc-5de6-a945-ff0defa34992', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 34, 34, 'In which direction does the steel wire pull on Jan?', 'diagram:circ-hammer-throw', 2, 'multiple_choice'::answer_type, 'Along the wire, towards the iron ball', NULL, NULL, false, 'A taut wire pulls on both of its ends. It pulls the ball inwards, towards Jan (the centripetal force), and by Newton’s third law it pulls Jan outwards, towards the ball, with a force of the same size — which is why a hammer thrower leans back.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('837d5d5e-3b45-57ab-ad94-dd649a27407a', '0fa5f4e5-11dc-5de6-a945-ff0defa34992', 'Along the wire, away from the iron ball', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a64de49e-883d-5e8d-b9f2-69ddb5280566', '0fa5f4e5-11dc-5de6-a945-ff0defa34992', 'Along the wire, towards the iron ball', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4a750ab6-edc6-5d9a-9d64-7f2f8cbf8b07', '0fa5f4e5-11dc-5de6-a945-ff0defa34992', 'In the direction of the ball’s velocity', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8159b24f-af71-5b69-8954-927ab6007bd9', '0fa5f4e5-11dc-5de6-a945-ff0defa34992', 'It does not pull on Jan at all — it only pulls the ball', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5c6959bc-5025-5225-aa46-bdc88465148b', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 35, 35, 'The iron ball moves round its horizontal circle at a constant speed. Why is a horizontal force needed on the ball?', 'diagram:circ-hammer-throw', 2, 'multiple_choice'::answer_type, 'Its velocity is always changing direction, so it is accelerating, and by Newton’s second law an acceleration needs a resultant force', NULL, NULL, false, 'Constant speed is not constant velocity. The ball’s direction keeps changing, so its velocity changes: it accelerates towards the centre. By F = ma that needs a resultant force towards the centre, supplied by the tension in the wire.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7be79c13-77f6-5d9f-9d6f-ebedbf714030', '5c6959bc-5025-5225-aa46-bdc88465148b', 'Its velocity is always changing direction, so it is accelerating, and by Newton’s second law an acceleration needs a resultant force', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c64cdfd6-e3a7-5664-86c2-cf0c36952ac3', '5c6959bc-5025-5225-aa46-bdc88465148b', 'To keep its speed constant against its tendency to slow down', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('133ba09f-8123-50cc-97ee-5b2e3f354248', '5c6959bc-5025-5225-aa46-bdc88465148b', 'To balance the outward centrifugal force on the ball', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('804aa6fa-4a98-5fd3-b5e2-2c0298cabf0b', '5c6959bc-5025-5225-aa46-bdc88465148b', 'No force is needed, because the speed is constant', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('abac6f1c-a2d9-5c4d-8e3c-88666c43a1cb', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 36, 36, 'The 10 kg iron ball goes round a horizontal circle of radius 2.0 m, taking 1.5 s for each rotation. Calculate the centripetal force on the ball.', 'diagram:circ-hammer-throw', 2, 'numeric'::answer_type, '350.9', 'N', NULL, false, 'v = 2πr/T = 2π × 2.0 ÷ 1.5 = 8.38 m/s, so F = mv²/r = 10 × 8.38² ÷ 2.0 = 351 N. (Or F = mrω², with ω = 2π/T = 4.19 rad/s.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('08228984-577c-53e2-801d-4e1910906207', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 37, 37, 'After a few rotations the ball moves round a circle of the same radius, but with a shorter period. What happens to the horizontal force that the wire exerts on Jan?', 'diagram:circ-hammer-throw', 2, 'multiple_choice'::answer_type, 'It increases, because the centripetal force F = 4π²mr/T² gets bigger as T gets smaller', NULL, NULL, false, 'A shorter period means a higher speed (v = 2πr/T), and the centripetal force mv²/r = 4π²mr/T² depends on 1/T². The wire must pull harder on the ball — and so, by Newton’s third law, harder on Jan too. Halving the period would quadruple the force.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d2fab304-93fb-5df6-b1d8-445c38ed66d0', '08228984-577c-53e2-801d-4e1910906207', 'It decreases, because the ball takes less time to go round', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('940c9236-9635-5513-ba48-8c1902b6f97d', '08228984-577c-53e2-801d-4e1910906207', 'It stays the same, because the radius has not changed', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2232a66c-8548-5888-bcf8-ecfc1ebb3d29', '08228984-577c-53e2-801d-4e1910906207', 'It increases, because the centripetal force F = 4π²mr/T² gets bigger as T gets smaller', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bd449e5a-d482-5c92-85fc-9cba5ad2c845', '08228984-577c-53e2-801d-4e1910906207', 'It increases, but only in proportion to 1/T', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e0eaf77f-f440-5018-bc25-57ee89830cf7', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 38, 38, 'An 18 kg suitcase rides on a horizontal circular conveyor belt of radius 7.0 m. The unbalanced (resultant) force on it is 5.5 N. Calculate the time the belt takes to complete one rotation.', 'diagram:circ-baggage-belt', 3, 'numeric'::answer_type, '30.07', 's', NULL, false, 'The unbalanced force is the centripetal force: F = m × 4π²r/T². Rearranging, T = √(m × 4π²r ÷ F) = √(18 × 4π² × 7.0 ÷ 5.5) = √904 = 30.1 s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0b021dc0-df4b-506c-bb27-e162155b7e68', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 39, 39, 'Jason (mass 65 kg) stands on a merry-go-round, 4.0 m from its centre. The merry-go-round takes 15 s to make a complete turn. Calculate the centripetal force needed to keep him moving in his circle.', 'diagram:circ-merry-go-round', 2, 'numeric'::answer_type, '45.62', 'N', NULL, false, 'ω = 2π/T = 2π ÷ 15 = 0.419 rad/s, so F = mrω² = 65 × 4.0 × 0.419² = 45.6 N. (Or v = 2πr/T = 1.68 m/s and F = mv²/r.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ddc1c884-ecc7-5ea0-9ca4-effa41f9f4e6', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 40, 40, 'Janet’s ball moves round a horizontal circle of radius 0.75 m, taking 0.84 s to go round her head once. Calculate the acceleration of the ball.', 'diagram:circ-ball-overhead', 2, 'numeric'::answer_type, '41.96', 'm/s²', NULL, false, 'a = 4π²r/T² = 4π² × 0.75 ÷ 0.84² = 29.6 ÷ 0.7056 = 42.0 m/s², towards the centre of the circle. (Or v = 2πr/T = 5.61 m/s and a = v²/r.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f11c8962-32b7-54c5-bea0-49392c1ea3f6', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 41, 41, 'Which force makes Janet’s ball accelerate as it goes round its circle, and how does it change the ball’s velocity?', 'diagram:circ-ball-overhead', 2, 'multiple_choice'::answer_type, 'The tension in the string: it acts towards the centre, at right angles to the velocity, so it changes the ball’s direction but not its speed', NULL, NULL, false, 'The string pulls the ball towards the centre of the circle. That force is always perpendicular to the ball’s velocity, so it does no work and the speed stays the same — but it continually changes the direction of the velocity, which is a centripetal acceleration.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('429f67c2-07c0-5c20-9d3a-683b887b25cd', 'f11c8962-32b7-54c5-bea0-49392c1ea3f6', 'The ball’s weight: it acts towards the centre of the circle', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('400d5de6-77e4-595d-b191-c3932e834af2', 'f11c8962-32b7-54c5-bea0-49392c1ea3f6', 'The tension in the string: it acts along the direction of motion and speeds the ball up', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c2f299af-f62c-5ba7-b7a9-65cea8dfb7a8', 'f11c8962-32b7-54c5-bea0-49392c1ea3f6', 'Air resistance: it acts against the motion and turns the ball', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cf5c0323-9309-5719-b555-760e3809132b', 'f11c8962-32b7-54c5-bea0-49392c1ea3f6', 'The tension in the string: it acts towards the centre, at right angles to the velocity, so it changes the ball’s direction but not its speed', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('98f44fc1-9677-587f-9e53-de536495f019', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 42, 42, 'The referee’s 40.0 g whistle moves round a horizontal circle of radius 0.500 m, taking 1.40 s for each rotation. Calculate the horizontal force that the string exerts on the whistle.', 'diagram:circ-whistle-plan', 2, 'numeric'::answer_type, '0.4028', 'N', NULL, false, 'v = 2πr/T = 2π × 0.500 ÷ 1.40 = 2.24 m/s, and 40.0 g = 0.0400 kg. The string’s horizontal pull is the centripetal force: F = mv²/r = 0.0400 × 2.24² ÷ 0.500 = 0.403 N, towards the centre.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dcb15518-9424-56c9-939e-b445aaa87dd5', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 43, 43, 'Considering the horizontal forces on the whistle, why does it keep moving round its circle at a constant speed?', 'diagram:circ-whistle-plan', 2, 'multiple_choice'::answer_type, 'The only horizontal force is the string’s pull towards the centre; being at right angles to the velocity, it changes the direction of motion but not the speed', NULL, NULL, false, 'Horizontally the only force is the string’s tension (ignoring air resistance). It points towards the centre, perpendicular to the whistle’s velocity. A force at right angles to the motion does no work, so the speed stays the same, but it keeps turning the velocity — so the whistle goes round in a circle.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('20f3454e-45ce-5f41-8e0d-a1ac9902d2cc', 'dcb15518-9424-56c9-939e-b445aaa87dd5', 'The horizontal forces on it are balanced, so it keeps moving at a constant speed', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1bb37da2-36e5-5a36-a215-6e6332d44b61', 'dcb15518-9424-56c9-939e-b445aaa87dd5', 'The string’s pull balances an outward centrifugal force', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('27c3c646-92c9-500c-85ec-38b2fe28ce71', 'dcb15518-9424-56c9-939e-b445aaa87dd5', 'The string’s pull acts along the direction of motion, keeping the speed up', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fc948229-6f6b-5ffa-8757-a078d8782ba4', 'dcb15518-9424-56c9-939e-b445aaa87dd5', 'The only horizontal force is the string’s pull towards the centre; being at right angles to the velocity, it changes the direction of motion but not the speed', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1b83a2f9-8ad1-5287-bd1d-91eb2e964067', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 44, 44, 'The speed of the 40.0 g whistle is reduced to 1.0 m/s, still on a circle of radius 0.500 m. Calculate the new horizontal force needed to keep it moving in the circle.', 'diagram:circ-whistle-plan', 2, 'numeric'::answer_type, '0.08', 'N', NULL, false, 'F = mv²/r = 0.0400 × 1.0² ÷ 0.500 = 0.080 N — about five times smaller than before, because F depends on v².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('75a649a4-9b20-5788-998e-f544c0f4f150', 'a86aff95-adbc-4634-af1f-528e375e2230', 'db2c98d5-dd86-5faf-9121-5533bdd5d212', 'a-level', '12.2', '9702 12.2 Centripetal acceleration', 45, 45, 'At 1.0 m/s the whistle needs a horizontal force of only 0.080 N, while its weight is about 0.39 N. What is the likely result of reducing its speed?', 'diagram:circ-whistle-plan', 3, 'multiple_choice'::answer_type, 'The string sags: the whistle drops lower and moves round a smaller circle, with the string at a steeper angle', NULL, NULL, false, 'The string has to hold the whistle up as well as pull it round: the vertical part of the tension balances the weight and the horizontal part is the centripetal force. When the horizontal force needed falls to 0.080 N — far less than the weight — the string hangs much more steeply, like a conical pendulum, so the whistle drops and circles on a smaller radius.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2d8a0bbc-85ea-527e-b4a1-9f6d5225e099', '75a649a4-9b20-5788-998e-f544c0f4f150', 'The whistle keeps moving in the same horizontal circle, just more slowly', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ee5c5aba-f3fa-538a-86bc-f01247cf9e9d', '75a649a4-9b20-5788-998e-f544c0f4f150', 'The whistle flies off along a tangent', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('14c5c788-e333-5c78-bada-9f2a34adf625', '75a649a4-9b20-5788-998e-f544c0f4f150', 'The string sags: the whistle drops lower and moves round a smaller circle, with the string at a steeper angle', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2ffff6b1-ba09-58a6-8db9-d365005375e6', '75a649a4-9b20-5788-998e-f544c0f4f150', 'The whistle moves outwards into a bigger circle', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0c9dfca4-72af-53d6-a7ea-f07f704bda33', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '13.1', '9702 13.1 Gravitational field', 1, 1, 'What is a gravitational field?', NULL, 1, 'multiple_choice'::answer_type, 'A region in which a mass experiences a force', NULL, NULL, false, 'A gravitational field is a field of force: a region of space in which any mass placed there experiences a gravitational force. Every mass is surrounded by one — it is the “area of influence” through which masses attract each other without touching.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('72f842fc-16df-5516-bd45-e3a597cdf703', '0c9dfca4-72af-53d6-a7ea-f07f704bda33', 'A region in which an electric charge experiences a force', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0b4059c3-391d-5a7d-8e53-077e0dbac594', '0c9dfca4-72af-53d6-a7ea-f07f704bda33', 'A region in which a mass experiences a force', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7ab7c25e-6a81-5c51-a8ef-1eddd36ab9f2', '0c9dfca4-72af-53d6-a7ea-f07f704bda33', 'The path followed by an object in orbit', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6a6d22d9-88a7-533c-b266-119a8b48fcc8', '0c9dfca4-72af-53d6-a7ea-f07f704bda33', 'The force between two masses divided by the distance between them', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2e4e1d6f-179d-510e-9c77-4164164d5937', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '13.1', '9702 13.1 Gravitational field', 2, 2, 'Gravitational field strength g at a point is defined as…', NULL, 1, 'multiple_choice'::answer_type, 'the gravitational force per unit mass on a small mass placed at that point', NULL, NULL, false, 'g = F/m, measured in N/kg. Near the Earth’s surface it is 9.81 N/kg, which is why it is also the acceleration of free fall, 9.81 m/s² (1 N/kg = 1 m/s²). The work done per unit mass from infinity defines the gravitational POTENTIAL, not the field strength.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('043fb8a3-9c09-56c1-bdd9-9e23fe6fc8a0', '2e4e1d6f-179d-510e-9c77-4164164d5937', 'the gravitational force per unit mass on a small mass placed at that point', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('acfc6402-9c98-5685-9adb-0294bc114628', '2e4e1d6f-179d-510e-9c77-4164164d5937', 'the gravitational force on any object placed at that point', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d22ec2e6-afb1-5983-a59e-917b9f248804', '2e4e1d6f-179d-510e-9c77-4164164d5937', 'the work done per unit mass in bringing a small mass from infinity to that point', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('430c3968-144b-5970-b639-3b32e08d4241', '2e4e1d6f-179d-510e-9c77-4164164d5937', 'the mass per unit volume of the body producing the field', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9dcbdd37-7d72-5f7b-a664-4c8e88e93db1', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '13.1', '9702 13.1 Gravitational field', 3, 3, 'Is gravitational field strength a scalar or a vector quantity?', NULL, 1, 'multiple_choice'::answer_type, 'A vector, because it is a force per unit mass and so has a direction', NULL, NULL, false, 'Gravitational fields are force fields. Force is a vector, so force per unit mass is a vector too: at every point g has a size and a direction (towards the mass producing the field). That is why fields are drawn with arrows.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('25251659-9b0e-552c-9dbf-2e3ebc45e6a4', '9dcbdd37-7d72-5f7b-a664-4c8e88e93db1', 'A scalar, because it only has a size', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2b70e3b4-f88a-5cc3-af81-92353739b49d', '9dcbdd37-7d72-5f7b-a664-4c8e88e93db1', 'A scalar, because mass is a scalar', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d161ad16-4802-56b6-859c-def373ad4e7e', '9dcbdd37-7d72-5f7b-a664-4c8e88e93db1', 'A vector, because it is a force per unit mass and so has a direction', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a265747d-6e8e-592f-bcf5-7d66dc9b424e', '9dcbdd37-7d72-5f7b-a664-4c8e88e93db1', 'A vector, but only close to the Earth’s surface', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1fc76c37-8553-5479-bde7-c54540318c7e', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '13.1', '9702 13.1 Gravitational field', 4, 4, 'The diagram shows field lines around a planet. What does the spacing of the field lines show?', 'diagram:grav-field-lines', 2, 'multiple_choice'::answer_type, 'The field strength: it is strongest where the lines are closest together', NULL, NULL, false, 'The arrows show the direction of the force on a mass (towards the planet) and the density of the lines shows the field strength. The lines crowd together near the surface, where the field is strongest, and spread out further away, where it is weaker.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('df0fef0a-44c1-5470-adc7-13272dd327aa', '1fc76c37-8553-5479-bde7-c54540318c7e', 'The field strength: it is strongest where the lines are furthest apart', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('296a42e4-651b-5536-ac7f-1551e68bb5a1', '1fc76c37-8553-5479-bde7-c54540318c7e', 'The direction in which masses near the planet are moving', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('11a9df00-50aa-5871-83fb-009f4205b081', '1fc76c37-8553-5479-bde7-c54540318c7e', 'Nothing — only the direction of the arrows has any meaning', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a3125bee-1053-545b-a9de-27a0ad4ea7df', '1fc76c37-8553-5479-bde7-c54540318c7e', 'The field strength: it is strongest where the lines are closest together', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7208dff5-fca1-58b5-9032-092f0f8245be', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', '748a497a-deae-518a-a929-236d0930052b', 'a-level', '13.1', '9702 13.1 Gravitational field', 5, 5, 'An astronaut travels from the Earth to the Moon. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Her mass stays the same, but her weight changes', NULL, NULL, false, 'Mass is the amount of matter in her body and is the same everywhere. Weight is the gravitational force on her, W = mg, so it depends on the field strength where she is — on the Moon g is only about 1.6 N/kg, so she weighs about a sixth of her weight on Earth.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a6f8c28c-aee4-51d4-9ccb-a5bdd644fa24', '7208dff5-fca1-58b5-9032-092f0f8245be', 'Her weight stays the same, but her mass changes', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('85caa3c9-0277-5e62-ab48-125d300c4e48', '7208dff5-fca1-58b5-9032-092f0f8245be', 'Both her mass and her weight stay the same', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3d59570f-1cd6-5fb3-99e1-2050ecb0bcc2', '7208dff5-fca1-58b5-9032-092f0f8245be', 'Her mass stays the same, but her weight changes', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('93a7f1a4-31b3-5373-8f37-8c8dd2734c0a', '7208dff5-fca1-58b5-9032-092f0f8245be', 'Both her mass and her weight change', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d0e7de7c-ec46-596f-8610-95a8d6a2bf82', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 1, 1, 'According to Newton’s law of gravitation, the gravitational force between two point masses is…', NULL, 1, 'multiple_choice'::answer_type, 'proportional to the product of their masses and inversely proportional to the square of their separation', NULL, NULL, false, 'F = Gm₁m₂/r², where r is the distance between the centres of mass and G = 6.67 × 10⁻¹¹ N m² kg⁻². Doubling one mass doubles the force; doubling the separation quarters it.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('87ab8c41-fa36-5c31-b839-f3c94fd925dd', 'd0e7de7c-ec46-596f-8610-95a8d6a2bf82', 'proportional to the sum of their masses and inversely proportional to their separation', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a1e6f716-5597-5ada-adbc-38441e0a4266', 'd0e7de7c-ec46-596f-8610-95a8d6a2bf82', 'proportional to the product of their masses and inversely proportional to their separation', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('beabdd5c-cf8d-5268-a4ac-d80bcb19ed0d', 'd0e7de7c-ec46-596f-8610-95a8d6a2bf82', 'proportional to the product of their masses and inversely proportional to the square of their separation', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c02723e4-dbd4-53c9-b084-5684dc44e27d', 'd0e7de7c-ec46-596f-8610-95a8d6a2bf82', 'proportional to the product of their masses and to the square of their separation', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e1c2e6c0-4024-5a26-a2af-b3ea17969969', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 2, 2, 'Two students, each of mass 75 kg, stand with their centres of mass 0.95 m apart. Treating them as point masses, calculate the gravitational force between them. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-two-students', 2, 'numeric'::answer_type, '4.157e-7', 'N', NULL, false, 'F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 75 × 75 ÷ 0.95² = 4.16 × 10⁻⁷ N — far too small to notice, which is why we only feel the gravity of huge masses like the Earth.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4909fe2e-3167-593f-bfae-ef3e73865b44', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 3, 3, 'A satellite weighs 9000 N on the Earth’s surface. What would the gravitational force on it be if its mass were tripled and it were moved to twice its distance from the Earth’s centre?', 'diagram:grav-weight-scaling', 3, 'numeric'::answer_type, '6750', 'N', NULL, false, 'F = GMm/r², so F ∝ m/r². Tripling m multiplies the force by 3; doubling r divides it by 2² = 4. New force = 9000 × 3 ÷ 4 = 6750 N.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4730b419-21fb-5f07-a96c-6b1e2647e8f2', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 4, 4, 'The Moon is pulled towards the Earth by gravity. Why doesn’t it fall down onto the Earth?', 'diagram:grav-moon-orbit', 2, 'multiple_choice'::answer_type, 'It is falling towards the Earth all the time, but its sideways speed carries it round the Earth instead of into it', NULL, NULL, false, 'Gravity is the centripetal force on the Moon. It accelerates the Moon towards the Earth continuously, but because the Moon is also moving sideways, this “falling” only bends its path into a circle round the Earth. The same is true of any satellite — which is why astronauts in orbit feel weightless: they are in free fall.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4a17fa4b-413c-5886-b3b0-709694ec5c0b', '4730b419-21fb-5f07-a96c-6b1e2647e8f2', 'The Earth’s gravity does not reach as far as the Moon', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('07b78c1c-8235-53b8-a9b7-1a992d02fe43', '4730b419-21fb-5f07-a96c-6b1e2647e8f2', 'An outward centrifugal force on the Moon balances the Earth’s gravity', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b5b24b35-1d32-5f92-aebb-e20992c42068', '4730b419-21fb-5f07-a96c-6b1e2647e8f2', 'It is falling towards the Earth all the time, but its sideways speed carries it round the Earth instead of into it', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1959f5f3-a979-5ec2-a8c6-04ef6c8184a2', '4730b419-21fb-5f07-a96c-6b1e2647e8f2', 'The Sun’s gravity pulls it away from the Earth just as strongly', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('585e03fa-7cd5-5269-8b88-dd731069bfbc', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 5, 5, 'A 4500 kg satellite orbits the Earth at an orbital radius of 8.50 × 10⁷ m. Calculate its orbital speed. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.98 × 10²⁴ kg.', 'diagram:grav-orbit-85e7', 3, 'numeric'::answer_type, '2166', 'm/s', NULL, false, 'Gravity provides the centripetal force: GMm/r² = mv²/r. The satellite’s mass cancels, so v = √(GM/r) = √(6.67 × 10⁻¹¹ × 5.98 × 10²⁴ ÷ 8.50 × 10⁷) = √(4.69 × 10⁶) = 2.17 × 10³ m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fd627ab0-9186-571a-ab38-4b5f90d3a44f', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 6, 6, 'A satellite orbits the Earth at a radius of 2.20 × 10⁷ m. Calculate its orbital period. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.98 × 10²⁴ kg.', 'diagram:grav-orbit-22e7', 3, 'numeric'::answer_type, '32464', 's', NULL, false, 'GMm/r² = m × 4π²r/T², so T² = 4π²r³/(GM) = 4π² × (2.20 × 10⁷)³ ÷ (6.67 × 10⁻¹¹ × 5.98 × 10²⁴) = 1.05 × 10⁹ s², and T = 3.25 × 10⁴ s — about 9 hours.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('03ecb07d-a234-5578-a646-699c13d22882', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 7, 7, 'Two identical satellites orbit the Earth. Satellite A’s orbital radius is twice satellite B’s. Which satellite travels faster?', 'diagram:grav-two-orbits', 2, 'multiple_choice'::answer_type, 'B — it is closer, where the gravitational pull is stronger, so it must move faster to stay in orbit', NULL, NULL, false, 'For a circular orbit v = √(GM/r). The closer satellite feels a stronger pull, so it needs a larger speed for that pull to be exactly the centripetal force it needs. Here v_B = √2 × v_A ≈ 1.41 v_A.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('97c9db2d-3a02-5bd8-9c10-d66522a73331', '03ecb07d-a234-5578-a646-699c13d22882', 'A — it has further to travel in each orbit', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bc4d9f14-3a15-5489-95d0-c757c6dcf979', '03ecb07d-a234-5578-a646-699c13d22882', 'Neither — identical satellites travel at the same speed', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('394d4604-d8a0-50eb-a505-12a3c285a878', '03ecb07d-a234-5578-a646-699c13d22882', 'A — the weaker pull on it slows it down less', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('edb1d471-3625-50a7-8e4a-6ebcb08fc2e7', '03ecb07d-a234-5578-a646-699c13d22882', 'B — it is closer, where the gravitational pull is stronger, so it must move faster to stay in orbit', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3af1d7dd-21ad-514e-a4db-7d422df5481f', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 8, 8, 'Two identical satellites are in circular orbits of the same radius: A orbits the Sun and B orbits the Earth. Which satellite travels faster?', 'diagram:grav-sun-earth', 2, 'multiple_choice'::answer_type, 'A — the Sun’s much larger mass gives a stronger pull at that radius, so A must move faster to stay in orbit', NULL, NULL, false, 'v = √(GM/r): at the same radius, the orbital speed depends only on the mass M of the central body. The Sun is about 330 000 times as massive as the Earth, so A must travel about √330 000 ≈ 575 times as fast.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f7871c95-1311-5a37-b335-96e6960e2d97', '3af1d7dd-21ad-514e-a4db-7d422df5481f', 'B — the Earth is smaller, so B goes round it more quickly', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('25039d47-1d8e-5007-b05c-91632bac6646', '3af1d7dd-21ad-514e-a4db-7d422df5481f', 'Neither — at the same orbital radius the speeds are equal', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8b6b22cb-3192-5608-87d0-397428be7af6', '3af1d7dd-21ad-514e-a4db-7d422df5481f', 'B — the Sun’s stronger pull slows A down', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a045690b-ab54-58da-814a-ca13a9465913', '3af1d7dd-21ad-514e-a4db-7d422df5481f', 'A — the Sun’s much larger mass gives a stronger pull at that radius, so A must move faster to stay in orbit', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fe192ca9-5f81-51c4-b88b-cfb0e758cb57', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 9, 9, 'A geostationary satellite stays above the same point on the equator: it orbits once in the time the Earth takes to spin once, 24 hours. Calculate the radius of its orbit. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.98 × 10²⁴ kg.', 'diagram:grav-geostationary', 4, 'numeric'::answer_type, '4.225e7', 'm', NULL, false, 'T = 24 × 3600 = 86 400 s. From GMm/r² = m × 4π²r/T², r³ = GMT²/(4π²) = 6.67 × 10⁻¹¹ × 5.98 × 10²⁴ × 86 400² ÷ 4π² = 7.54 × 10²² m³, so r = 4.23 × 10⁷ m — about 36 000 km above the surface.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b4c673ba-ed12-5a5f-9409-7f328fa72193', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 10, 10, 'A geostationary satellite orbits at a radius of 4.22 × 10⁷ m, going round once every 24 hours. Calculate its orbital speed.', 'diagram:grav-geostationary', 3, 'numeric'::answer_type, '3069', 'm/s', NULL, false, 'T = 24 h = 86 400 s. v = 2πr/T = 2π × 4.22 × 10⁷ ÷ 86 400 = 3.07 × 10³ m/s.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d9da45e0-568b-5833-a496-8b01f6e2ce4a', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 11, 11, 'A spaceship goes into a circular orbit around a planet, at a height of 351 km above the planet’s surface, with a period of 5.46 × 10³ s. The planet’s radius is 5220 km. Calculate the mass of the planet. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-spaceship-planet', 4, 'numeric'::answer_type, '3.433e24', 'kg', NULL, false, 'Measure the orbital radius from the planet’s centre: r = 5220 km + 351 km = 5571 km = 5.571 × 10⁶ m. Gravity provides the centripetal force, GMm/r² = mrω² with ω = 2π/T, so M = 4π²r³/(GT²) = 4π² × (5.571 × 10⁶)³ ÷ (6.67 × 10⁻¹¹ × (5.46 × 10³)²) = 3.43 × 10²⁴ kg.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('04cbeacc-6f5a-5478-be06-5f93328db633', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 12, 12, 'A 300 kg television satellite is in a geostationary orbit round the Earth. Name the force that keeps it in its circular orbit, and state the direction in which this force acts.', 'diagram:grav-tv-satellite', 1, 'multiple_choice'::answer_type, 'The gravitational pull of the Earth, towards the centre of the Earth', NULL, NULL, false, 'Gravity (the satellite’s weight) is the only force acting on it. It points towards the centre of the Earth, at right angles to the satellite’s velocity — exactly what is needed to provide the centripetal force for a circular orbit. No engine is needed to stay in orbit.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ac8b385c-eaec-5fef-bd1d-4735709fb802', '04cbeacc-6f5a-5478-be06-5f93328db633', 'The gravitational pull of the Earth, along the direction of the satellite’s motion', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6be47bcf-81a8-5643-8a1d-c8c78b40aef4', '04cbeacc-6f5a-5478-be06-5f93328db633', 'A centrifugal force, away from the Earth', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d479a3e2-aed5-56ae-8ad4-8dddb74dbec4', '04cbeacc-6f5a-5478-be06-5f93328db633', 'The gravitational pull of the Earth, towards the centre of the Earth', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c54dcae9-404f-50d6-ae8e-a88252395f5f', '04cbeacc-6f5a-5478-be06-5f93328db633', 'The thrust of the satellite’s engines, towards the centre of the Earth', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f800de10-181c-5593-9243-a7c16c85f104', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 13, 13, 'The 300 kg television satellite orbits at a radius of 4.22 × 10⁷ m from the centre of the Earth. Calculate the gravitational force on it. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.97 × 10²⁴ kg.', 'diagram:grav-tv-satellite', 2, 'numeric'::answer_type, '67.08', 'N', NULL, false, 'F = GMm/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 300 ÷ (4.22 × 10⁷)² = 67.1 N — compared with about 2900 N at the Earth’s surface.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('48b5be4c-770f-54cb-ada0-cdf18092b31d', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 14, 14, 'Calculate the orbital speed of the television satellite, which orbits at a radius of 4.22 × 10⁷ m. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.97 × 10²⁴ kg.', 'diagram:grav-tv-satellite', 3, 'numeric'::answer_type, '3072', 'm/s', NULL, false, 'The gravitational force is the centripetal force: GMm/r² = mv²/r, so v = √(GM/r) = √(6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ 4.22 × 10⁷) = 3.07 × 10³ m/s. (Check: 2πr/T with T = 24 h gives the same.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e00b6583-fe7d-5f99-856b-33447e63d75c', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 15, 15, 'The space shuttle Discovery, with the Hubble space telescope attached to it by a cable, is in a circular orbit of radius 7.00 × 10⁶ m. Which force keeps the shuttle and telescope in their orbit, and in which direction does it act?', 'diagram:grav-shuttle-orbit', 1, 'multiple_choice'::answer_type, 'The Earth’s gravitational force, directed towards the centre of the Earth', NULL, NULL, false, 'The only significant force on the shuttle–telescope system is the Earth’s gravity. It acts towards the Earth’s centre, perpendicular to the velocity, and is the centripetal force of the orbit. The cable’s tension is an internal force between the shuttle and the telescope, so it does not affect the motion of the system as a whole.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4812980e-fca8-5d00-9c3c-da7d312efec2', 'e00b6583-fe7d-5f99-856b-33447e63d75c', 'The Earth’s gravitational force, directed along the shuttle’s velocity', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('424dea81-1125-5038-9d25-e2173a055ef8', 'e00b6583-fe7d-5f99-856b-33447e63d75c', 'The Earth’s gravitational force, directed towards the centre of the Earth', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5baf5982-4a64-5fbb-91d7-e00474776657', 'e00b6583-fe7d-5f99-856b-33447e63d75c', 'The tension in the cable, directed towards the telescope', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0878c89a-8007-5c9d-9622-249bc4c34b11', 'e00b6583-fe7d-5f99-856b-33447e63d75c', 'A centrifugal force, directed away from the Earth', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('18e17b37-cb9b-5adf-9482-b864223fd26f', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 16, 16, 'Phobos, one of the moons of Mars, orbits Mars at a mean radius of 9.38 × 10⁶ m with a period of 2.76 × 10⁴ s. Calculate the mass of Mars. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-phobos', 4, 'numeric'::answer_type, '6.412e23', 'kg', NULL, false, 'Gravity provides Phobos’s centripetal force: GMm/r² = mrω², with ω = 2π/T = 2.28 × 10⁻⁴ rad/s. So M = ω²r³/G = 4π²r³/(GT²) = 4π² × (9.38 × 10⁶)³ ÷ (6.67 × 10⁻¹¹ × (2.76 × 10⁴)²) = 6.41 × 10²³ kg.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4f55c8d1-5c17-5c8b-8b67-333ef0f05bdc', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 17, 17, 'A planet of mass m moves in a circular orbit of radius r and period T round a star of mass M. Equating the gravitational force on the planet to the centripetal force it needs gives which relationship?', 'diagram:grav-star-planet', 3, 'multiple_choice'::answer_type, 'T² = (4π²/GM) r³', NULL, NULL, false, 'GMm/r² = mv²/r with v = 2πr/T. Substituting: GMm/r² = m(4π²r²/T²)/r = 4π²mr/T², so T² = (4π²/GM) r³. The planet’s mass cancels — and T² ∝ r³ is Kepler’s third law.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('06f2f25e-68f2-5762-8dda-67db779c035c', '4f55c8d1-5c17-5c8b-8b67-333ef0f05bdc', 'T² = (GM/4π²) r³', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c8f2380d-1102-564e-8632-b119809cbfa4', '4f55c8d1-5c17-5c8b-8b67-333ef0f05bdc', 'T² = (4π²/GM) r²', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('639e34af-c33f-5f2a-8118-d7ef049b98c9', '4f55c8d1-5c17-5c8b-8b67-333ef0f05bdc', 'T = (4π²/GM) r³', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7a45046b-ccfa-5c4b-aaa3-67e80c106e71', '4f55c8d1-5c17-5c8b-8b67-333ef0f05bdc', 'T² = (4π²/GM) r³', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9aa3c249-69e8-58c0-b046-6e2daa5a5e87', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 18, 18, 'By equating the gravitational force on a planet to the centripetal force it needs, find an expression for its orbital speed v in a circular orbit of radius r round a star of mass M.', 'diagram:grav-star-planet', 2, 'multiple_choice'::answer_type, 'v = √(GM/r)', NULL, NULL, false, 'GMm/r² = mv²/r. Cancel m and one factor of r: v² = GM/r, so v = √(GM/r). The orbital speed falls as the orbit gets bigger, and does not depend on the planet’s own mass.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('950e6b43-386f-5911-b27d-0efe4db319e4', '9aa3c249-69e8-58c0-b046-6e2daa5a5e87', 'v = √(GM/r)', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dd20dfdb-d056-522d-a1b4-a69e51c43add', '9aa3c249-69e8-58c0-b046-6e2daa5a5e87', 'v = √(GMr)', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('64f43684-9372-5b56-bfb2-20495b9450f2', '9aa3c249-69e8-58c0-b046-6e2daa5a5e87', 'v = GM/r', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2d9edcb0-587c-5065-abc5-73884a9bf8b4', '9aa3c249-69e8-58c0-b046-6e2daa5a5e87', 'v = √(GM/r²)', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2a486041-9097-5335-a64e-2244fd9c8f94', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 19, 19, 'F_E is the gravitational force exerted on the Earth by the Moon, and F_m is the gravitational force exerted on the Moon by the Earth. Which statement is correct?', 'diagram:grav-earth-moon', 2, 'multiple_choice'::answer_type, 'F_E and F_m are equal in size and opposite in direction: F_E acts on the Earth towards the Moon, and F_m acts on the Moon towards the Earth', NULL, NULL, false, 'The two forces are a Newton’s third law pair: both equal Gm₁m₂/r², so they are the same size, and they point towards each other along the line joining the centres. The Moon accelerates much more only because its mass is much smaller.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('42554ae9-ea1b-5e35-b35b-8d5efe06294b', '2a486041-9097-5335-a64e-2244fd9c8f94', 'F_E and F_m are equal in size and opposite in direction: F_E acts on the Earth towards the Moon, and F_m acts on the Moon towards the Earth', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f7a0af8a-08fa-5559-991a-8e551f3f07f9', '2a486041-9097-5335-a64e-2244fd9c8f94', 'F_E is much larger than F_m, because the Earth is much more massive', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1812381e-d464-5894-bfc3-f6806732b006', '2a486041-9097-5335-a64e-2244fd9c8f94', 'F_m is much larger than F_E, because the Moon is less massive', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e9bbf742-1e6e-5e5e-9e35-3a60d1fe33b3', '2a486041-9097-5335-a64e-2244fd9c8f94', 'F_E and F_m are equal in size, and both act towards the Earth', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6276bf8e-5bc1-59d8-b7f2-a2ec1a9f50f6', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 20, 20, 'The Earth has a mass of 5.97 × 10²⁴ kg and the Moon a mass of 7.35 × 10²² kg. Their centres are 3.84 × 10⁸ m apart. Calculate the gravitational force between the Earth and the Moon. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-earth-moon', 2, 'numeric'::answer_type, '1.985e20', 'N', NULL, false, 'F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 7.35 × 10²² ÷ (3.84 × 10⁸)² = 1.98 × 10²⁰ N.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d8f9424d-a317-51d5-9ef4-b29540d38c09', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 21, 21, 'The International Space Station (ISS), of mass 4.20 × 10⁵ kg, orbits the Earth at a height of 408 km above the Earth’s surface. Taking the radius of the Earth as 6.38 × 10⁶ m, calculate the distance between the centre of the Earth and the ISS.', 'diagram:grav-iss-orbit', 1, 'numeric'::answer_type, '6.788e6', 'm', NULL, false, 'Distances in the law of gravitation are measured from the centre of the Earth, so add the Earth’s radius to the height (in metres): r = 6.38 × 10⁶ + 408 × 10³ = 6.788 × 10⁶ m.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9132ad07-eef4-518a-8a40-10124a27ee88', 'ac5e5832-2f40-4487-ba6b-19b47d21baac', '1585a36a-5b5c-5505-abe3-98e37e28c48b', 'a-level', '13.2', '9702 13.2 Gravitational force between point masses', 22, 22, 'The ISS (mass 4.20 × 10⁵ kg) orbits 6.788 × 10⁶ m from the centre of the Earth. Calculate the gravitational force between the Earth and the ISS. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.97 × 10²⁴ kg.', 'diagram:grav-iss-orbit', 2, 'numeric'::answer_type, '3.63e6', 'N', NULL, false, 'F = GMm/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 4.20 × 10⁵ ÷ (6.788 × 10⁶)² = 3.63 × 10⁶ N — about 88% of the ISS’s weight on the ground.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c8ede94a-5dc2-5681-985e-21713b1f8176', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '13.3', '9702 13.3 Gravitational field of a point mass', 1, 1, 'A campfire seems to give out a “heat field”: it feels stronger as you move closer, and stronger again if the fire is made bigger. In what similar way does the gravitational field strength around a planet behave?', NULL, 1, 'multiple_choice'::answer_type, 'It is stronger closer to the planet, and stronger for a more massive planet', NULL, NULL, false, 'For a point mass — or a uniform sphere, outside it — g = GM/r²: g increases as the distance r from the centre decreases, and increases in proportion to the mass M.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b56c9ed5-6340-5829-b876-032fbe11d576', 'c8ede94a-5dc2-5681-985e-21713b1f8176', 'It is stronger closer to the planet, and stronger for a more massive planet', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('74129182-f404-576f-bb36-475d490f6861', 'c8ede94a-5dc2-5681-985e-21713b1f8176', 'It is stronger closer to the planet, but does not depend on the planet’s mass', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('64c75c93-28e2-5e84-baad-1782c333d6c4', 'c8ede94a-5dc2-5681-985e-21713b1f8176', 'It is the same at all distances, but stronger for a more massive planet', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ae609cdd-a643-5acd-968e-c024f9cbf347', 'c8ede94a-5dc2-5681-985e-21713b1f8176', 'It is weaker closer to the planet', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8c299a23-4cc7-53ef-932c-2f7104b2e0ab', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '13.3', '9702 13.3 Gravitational field of a point mass', 2, 2, 'Near the Earth’s surface we use g = 9.81 N/kg. Why can’t this value be used to find the gravitational force on a satellite in a high orbit?', NULL, 2, 'multiple_choice'::answer_type, 'Because g = GM/r² gets smaller as the distance r from the Earth’s centre increases', NULL, NULL, false, 'g is only roughly constant close to the surface, where r hardly changes. Further out g = GM/r² falls with the square of the distance from the Earth’s centre: at twice the Earth’s radius it is a quarter of 9.81 N/kg. Gravity never switches off in orbit — it is what keeps the satellite going round.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4cbd57db-1e6f-563a-b70d-8a4d87982d9e', '8c299a23-4cc7-53ef-932c-2f7104b2e0ab', 'Because g is zero once you are above the atmosphere', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8ea88b21-5472-5e6b-b068-6e18beecc5fa', '8c299a23-4cc7-53ef-932c-2f7104b2e0ab', 'Because g only applies to objects that are falling', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8c363421-bc91-56ce-b858-0005d5ab9c5f', '8c299a23-4cc7-53ef-932c-2f7104b2e0ab', 'Because the satellite’s mass changes in orbit', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1873cf14-4837-5274-abce-40788c15aa7b', '8c299a23-4cc7-53ef-932c-2f7104b2e0ab', 'Because g = GM/r² gets smaller as the distance r from the Earth’s centre increases', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0f651360-ec71-5986-beea-424b38ba7fc8', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '13.3', '9702 13.3 Gravitational field of a point mass', 3, 3, 'The Moon has a mass of 7.35 × 10²² kg and a radius of 1.74 × 10⁶ m. Calculate the gravitational field strength at its surface. Use G = 6.67 × 10⁻¹¹ N m² kg⁻².', 'diagram:grav-moon-radius', 2, 'numeric'::answer_type, '1.619', 'N/kg', NULL, false, 'g = GM/r² = 6.67 × 10⁻¹¹ × 7.35 × 10²² ÷ (1.74 × 10⁶)² = 1.62 N/kg — about a sixth of the value on Earth.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cbc54b2e-012f-5563-bee5-083f210fd2f2', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '13.3', '9702 13.3 Gravitational field of a point mass', 4, 4, 'The space shuttle and telescope orbit the Earth at a radius of 7.00 × 10⁶ m. Calculate the gravitational field strength (the acceleration due to gravity) at this height, giving your answer to an appropriate number of significant figures. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.98 × 10²⁴ kg.', 'diagram:grav-shuttle-orbit', 2, 'numeric'::answer_type, '8.14', 'N/kg', NULL, false, 'g = GM/r² = 6.67 × 10⁻¹¹ × 5.98 × 10²⁴ ÷ (7.00 × 10⁶)² = 8.14 N/kg, to 3 significant figures like the data. That is only about 17% less than at the surface — astronauts float because they are in free fall, not because gravity has gone.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f4343ac3-109f-570c-b7fc-0c7316a6b0db', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'f779851e-a0d7-547b-b5a0-d558fa4769be', 'a-level', '13.3', '9702 13.3 Gravitational field of a point mass', 5, 5, 'Calculate the gravitational field strength due to the Earth at any point in the orbit of the ISS, 6.788 × 10⁶ m from the Earth’s centre. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.97 × 10²⁴ kg.', 'diagram:grav-iss-orbit', 2, 'numeric'::answer_type, '8.642', 'N/kg', NULL, false, 'g = GM/r² = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ ÷ (6.788 × 10⁶)² = 8.64 N/kg. (Or divide the force on the ISS by its mass: 3.63 × 10⁶ N ÷ 4.20 × 10⁵ kg gives the same.)', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ac9660b4-c038-5631-afb9-282b670e5fa3', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 1, 1, 'In the expression Eₚ = −GMm/r for the gravitational potential energy of two masses, where is the zero of potential energy?', NULL, 1, 'multiple_choice'::answer_type, 'When the masses are infinitely far apart', NULL, NULL, false, 'Eₚ = −GMm/r tends to zero as r → ∞, so the reference point (Eₚ = 0) is infinite separation. The gravitational potential φ = −GM/r uses the same zero: it is the work done per unit mass in bringing a small mass from infinity.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3f8cb10f-639f-5341-8ff0-8201b6e977ab', 'ac9660b4-c038-5631-afb9-282b670e5fa3', 'When the masses are infinitely far apart', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0b9df76d-f876-51dc-9813-e5f8a4ba7099', 'ac9660b4-c038-5631-afb9-282b670e5fa3', 'When the masses are touching', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('af19d03a-1142-5655-9a9a-622595a31160', 'ac9660b4-c038-5631-afb9-282b670e5fa3', 'At the surface of the larger mass', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f5b2776d-c1f5-5c09-a569-4662e2e28d36', 'ac9660b4-c038-5631-afb9-282b670e5fa3', 'At the centre of the larger mass', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('eb61950f-21ad-51f1-b6b8-9d6ab9c09ec4', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 2, 2, 'Why is the gravitational potential energy of a mass near a planet always negative?', NULL, 2, 'multiple_choice'::answer_type, 'Its zero is at infinity and gravity is attractive: work must be done ON the mass to take it away to infinity, so at any finite distance it has less energy than at infinity', NULL, NULL, false, 'Bringing a mass in from infinity, gravity does work on it and its potential energy falls below the zero at infinity. To take it back out you would have to supply that energy. So at every finite distance Eₚ = −GMm/r is negative, and it gets more negative the closer the mass is.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('484eef6d-4627-57ba-af9b-97bd871c1b18', 'eb61950f-21ad-51f1-b6b8-9d6ab9c09ec4', 'Its zero is at infinity and gravity is attractive: work must be done ON the mass to take it away to infinity, so at any finite distance it has less energy than at infinity', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2910bb11-5aa7-5dc8-ae86-445fbb236bb4', 'eb61950f-21ad-51f1-b6b8-9d6ab9c09ec4', 'Because the mass is below the reference height, which is at the planet’s surface', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b689a6d2-5686-54a2-b123-6f296d2a4316', 'eb61950f-21ad-51f1-b6b8-9d6ab9c09ec4', 'Because gravitational forces are negative', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7a27e193-5caf-523b-b7dc-df7fced37aa3', 'eb61950f-21ad-51f1-b6b8-9d6ab9c09ec4', 'Because the mass is moving towards the planet', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4a386afa-359f-5388-bf1d-28580541fc20', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 3, 3, 'Which graph shows how the gravitational potential energy Eₚ of a mass varies with its distance r from the centre of a planet of radius R, for r ≥ R?', 'diagram:grav-ep-graphs', 2, 'multiple_choice'::answer_type, 'Graph C', NULL, NULL, false, 'Eₚ = −GMm/r: it is negative everywhere, most negative at the surface (r = R), and rises towards zero as r → ∞ — graph C. A has the wrong sign, B is a straight line (like mgh, which only works close to the surface), and D starts at zero and falls, which would mean the mass loses energy as it moves away.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a8ad760e-a92e-5a0a-baf3-404cceb746cc', '4a386afa-359f-5388-bf1d-28580541fc20', 'Graph A', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f2eb483f-ed7d-51bb-8cfc-4d9f25f555c5', '4a386afa-359f-5388-bf1d-28580541fc20', 'Graph B', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('526bf37c-2762-5668-a35b-29aea2cdd7b6', '4a386afa-359f-5388-bf1d-28580541fc20', 'Graph C', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cd3e6d91-ede9-5c70-8fbe-f17c8c755dd5', '4a386afa-359f-5388-bf1d-28580541fc20', 'Graph D', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('55f76991-a6a2-5daf-b026-7c9903b07b35', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 4, 4, 'A 2500 kg satellite is in orbit 3.60 × 10⁷ m above the Earth’s surface. Calculate its gravitational potential energy due to the Earth, including the sign. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the Earth’s mass as 5.98 × 10²⁴ kg and its radius as 6.38 × 10⁶ m.', 'diagram:grav-satellite-altitude', 3, 'numeric'::answer_type, '-2.353e10', 'J', 0.05, true, 'Measure r from the Earth’s centre: r = 3.60 × 10⁷ + 6.38 × 10⁶ = 4.238 × 10⁷ m. Eₚ = −GMm/r = −6.67 × 10⁻¹¹ × 5.98 × 10²⁴ × 2500 ÷ 4.238 × 10⁷ = −2.35 × 10¹⁰ J. It is negative because the zero of potential energy is at infinity.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5b3e9a90-4830-5a59-805b-b7ab7d677623', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 5, 5, 'The same 2500 kg satellite orbits 4.238 × 10⁷ m from the Earth’s centre. Calculate its total energy (kinetic plus gravitational potential), including the sign. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.98 × 10²⁴ kg.', 'diagram:grav-satellite-altitude', 4, 'numeric'::answer_type, '-1.176e10', 'J', 0.05, true, 'In a circular orbit GMm/r² = mv²/r, so v = √(GM/r) = 3.07 × 10³ m/s and Eₖ = ½mv² = GMm/(2r) = 1.18 × 10¹⁰ J. With Eₚ = −GMm/r = −2.35 × 10¹⁰ J, the total is E = Eₖ + Eₚ = −1.18 × 10¹⁰ J — exactly half of Eₚ. It is negative: the satellite is bound to the Earth.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cab67ad5-03ba-56bd-93bb-ebdc2726f8bb', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 6, 6, 'For a satellite in a circular orbit, how is its kinetic energy Eₖ related to its gravitational potential energy Eₚ?', NULL, 3, 'multiple_choice'::answer_type, 'Eₖ = −½Eₚ', NULL, NULL, false, 'In orbit GMm/r² = mv²/r, so mv² = GMm/r and Eₖ = ½mv² = GMm/(2r). Since Eₚ = −GMm/r, Eₖ = −½Eₚ — a positive number, because Eₚ is negative. The total energy is then Eₖ + Eₚ = ½Eₚ.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b11d6791-bd3a-5bf6-93f9-3507ed589888', 'cab67ad5-03ba-56bd-93bb-ebdc2726f8bb', 'Eₖ = −Eₚ', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4d5e710c-69c7-551f-97b0-b8eca78ae03b', 'cab67ad5-03ba-56bd-93bb-ebdc2726f8bb', 'Eₖ = ½Eₚ', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fdab367a-4d6c-5561-ad55-f20170ecb1d2', 'cab67ad5-03ba-56bd-93bb-ebdc2726f8bb', 'Eₖ = −2Eₚ', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6d788500-bbec-5547-ae9a-5a1f0baf4b4d', 'cab67ad5-03ba-56bd-93bb-ebdc2726f8bb', 'Eₖ = −½Eₚ', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8fe1f115-85d0-5013-acde-b4bdf738ba08', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 7, 7, 'How much work must be done to move a 4500 kg satellite from an orbital radius of 1.8 × 10⁷ m out to an orbital radius of 4.2 × 10⁷ m? Consider only the change in its gravitational potential energy (ignore any change in kinetic energy). Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the mass of the Earth as 5.98 × 10²⁴ kg.', 'diagram:grav-orbit-raise', 3, 'numeric'::answer_type, '5.698e10', 'J', NULL, false, 'W = ΔEₚ = (−GMm/r_f) − (−GMm/r_i) = GMm(1/r_i − 1/r_f) = 6.67 × 10⁻¹¹ × 5.98 × 10²⁴ × 4500 × (1/1.8 × 10⁷ − 1/4.2 × 10⁷) = 5.70 × 10¹⁰ J. It is positive: moving away from the Earth, the potential energy rises towards zero.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2946352c-54e8-55cf-be54-eb9404e1155f', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 8, 8, 'A 250 kg capsule of waste is released from rest at an altitude of 3.50 × 10⁵ m above the Earth’s surface. Ignoring air resistance, calculate the speed at which it would hit the Earth. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the Earth’s mass as 5.98 × 10²⁴ kg and its radius as 6.38 × 10⁶ m.', 'diagram:grav-iss-drop', 4, 'numeric'::answer_type, '2550', 'm/s', 0.05, false, 'r_i = 6.38 × 10⁶ + 3.50 × 10⁵ = 6.73 × 10⁶ m and r_f = 6.38 × 10⁶ m. The change in potential energy is ΔEₚ = GMm(1/r_i − 1/r_f) = −8.13 × 10⁸ J, so the capsule gains 8.13 × 10⁸ J of kinetic energy. ½mv² = 8.13 × 10⁸ J gives v = √(2 × 8.13 × 10⁸ ÷ 250) = 2.55 × 10³ m/s. (Using mgh with g = 9.81 N/kg would overestimate it, because g weakens with height.)', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('616e80ba-ba4f-5b40-b830-312fef33a36c', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 9, 9, 'An asteroid of mass 2.35 × 10¹⁶ kg starts from rest a very long way from the Earth (take its initial kinetic and potential energy as zero) and falls to the Earth. Calculate the energy released on impact — the kinetic energy it has when it reaches the Earth’s surface. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the Earth’s mass as 5.98 × 10²⁴ kg and its radius as 6.38 × 10⁶ m.', 'diagram:grav-asteroid', 3, 'numeric'::answer_type, '1.469e24', 'J', 0.05, false, 'Energy is conserved: Eₖ + Eₚ = 0 at the start, so at the surface Eₖ = −Eₚ = GMm/R = 6.67 × 10⁻¹¹ × 5.98 × 10²⁴ × 2.35 × 10¹⁶ ÷ 6.38 × 10⁶ = 1.47 × 10²⁴ J.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('222a825e-49a6-5305-ad5e-f69f4fb3b748', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 10, 10, 'To escape completely from the Earth’s gravitational field, an object launched from the surface must be given enough kinetic energy to…', NULL, 2, 'multiple_choice'::answer_type, 'make up for all of its (negative) gravitational potential energy, so that it can just reach infinity', NULL, NULL, false, 'At infinity Eₚ = 0. To get there the object needs at least enough kinetic energy to cancel its negative potential energy at the surface: ½mv² = GMm/R. That gives the escape speed, v = √(2GM/R). Reaching an orbit is not enough — an orbiting satellite is still bound to the Earth.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ff333b10-7a48-581b-92fd-3e71e668cb82', '222a825e-49a6-5305-ad5e-f69f4fb3b748', 'lift it to the top of the atmosphere', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('79d31369-ce52-557d-8f63-02ad86254098', '222a825e-49a6-5305-ad5e-f69f4fb3b748', 'make up for all of its (negative) gravitational potential energy, so that it can just reach infinity', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('60edca79-1c98-597d-9b28-5c8cf293e4dc', '222a825e-49a6-5305-ad5e-f69f4fb3b748', 'put it into a circular orbit', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2a45523b-5b4d-5ee7-90cd-4fa0ffb284f1', '222a825e-49a6-5305-ad5e-f69f4fb3b748', 'overcome its weight at the Earth’s surface', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('91cf01e2-2d2e-5e0b-9d77-68e9bdf0199e', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 11, 11, 'At what speed would you need to throw a 1.0 kg rock upwards from the Earth’s surface for it to escape completely from the Earth’s gravitational field? Ignore air resistance and the Earth’s rotation. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the Earth’s mass as 5.98 × 10²⁴ kg and its radius as 6.38 × 10⁶ m.', 'diagram:grav-escape', 3, 'numeric'::answer_type, '11182', 'm/s', NULL, false, 'At the minimum speed the total energy is zero: ½mv² − GMm/R = 0, so v = √(2GM/R) = √(2 × 6.67 × 10⁻¹¹ × 5.98 × 10²⁴ ÷ 6.38 × 10⁶) = 1.12 × 10⁴ m/s — about 11 km/s. The rock’s mass cancels.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1effc60f-c078-56ab-951b-1fd2cbd05e66', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 12, 12, 'Does the mass of the rock affect the speed it needs to escape from the Earth?', NULL, 2, 'multiple_choice'::answer_type, 'No: the mass cancels, so every object needs the same escape speed — but a heavier rock needs more kinetic energy to reach it', NULL, NULL, false, '½mv² = GMm/R: m appears on both sides and cancels, giving v = √(2GM/R) for any mass. The kinetic energy needed, ½mv², is still proportional to the mass, so a heavier rock needs more energy to be launched at the same speed.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e894c9cb-5719-534c-89ea-b6024e6ca636', '1effc60f-c078-56ab-951b-1fd2cbd05e66', 'No: the mass cancels, so every object needs the same escape speed — but a heavier rock needs more kinetic energy to reach it', 'A', true, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('13564d66-06a5-5947-b70b-841fec70c07d', '1effc60f-c078-56ab-951b-1fd2cbd05e66', 'Yes: a heavier rock needs a higher escape speed', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('62527a4b-50c4-53c6-a053-3d975c1413c7', '1effc60f-c078-56ab-951b-1fd2cbd05e66', 'Yes: a heavier rock needs a lower escape speed, because gravity pulls it harder', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bee315b8-fbe7-5e7b-ba91-43ca284511b8', '1effc60f-c078-56ab-951b-1fd2cbd05e66', 'No: and a heavier rock also needs no more kinetic energy', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cb312755-f2cf-5cc4-ad0d-f13da5c3ee41', 'ecdccf4c-21ed-53ba-9d9d-c67e8c623cc6', 'd22251cb-cf0a-5cdb-a0a6-bea9552467ec', 'a-level', '13.4', '9702 13.4 Gravitational potential', 13, 13, 'A 1450 kg satellite moves from an orbit 980 km above the Earth’s surface to a lower orbit 480 km above the surface. Calculate the change in its gravitational potential energy, including the sign. Use G = 6.67 × 10⁻¹¹ N m² kg⁻² and take the Earth’s mass as 5.97 × 10²⁴ kg and its radius as 6.38 × 10⁶ m.', 'diagram:grav-orbit-lower', 3, 'numeric'::answer_type, '-5.718e9', 'J', NULL, true, 'Radii from the Earth’s centre: r₁ = 6.38 × 10⁶ + 980 × 10³ = 7.36 × 10⁶ m and r₂ = 6.38 × 10⁶ + 480 × 10³ = 6.86 × 10⁶ m. ΔEₚ = Eₚ(final) − Eₚ(initial) = GMm(1/r₁ − 1/r₂) = 6.67 × 10⁻¹¹ × 5.97 × 10²⁴ × 1450 × (1/7.36 × 10⁶ − 1/6.86 × 10⁶) = −5.72 × 10⁹ J. It is negative: moving closer to the Earth, the potential energy decreases.', 3) ON CONFLICT (id) DO NOTHING;
